```cpp
#include <iostream>
#include <cctype>

int main() {
    char c;

    std::cout << "Connais-tu Llama?" << std::endl;
    while ((c = std::tolower(std::cin.get())) != '\n') {
        switch (c) {
            case 'o':
                std::cout << "Rien ne vaut, Llama est un éléphant !" << std::endl;
                break;
            case 'n':
                std::cout << "Je m'en fiche !" << std::endl;
                break;
            default:
                std::cout << "Syntax error. Typo ?" << std::endl;
                break;
        }
    }
    return 0;
}
```

