¡Claro! Diseñar un juego de tipo casual y match-3 como Bejeweled en Unity con C# será un desafío emocionante. Aquí te presento los pasos básicos para empezar:

**Preparación**

1. Crear un nuevo proyecto en Unity con un juego 2D.
2. Crear un nuevo asset bundle para almacenar nuestros recursos (imagens, audios, etc.).
3. Importar o crear las imágenes necesarias para el juego (piezas, fondo, etc.).

**Clase para representar las piezas**

En C#, crearemos una clase `GamePiece` para representar cada pieza en el juego:
```csharp
public class GamePiece : MonoBehaviour
{
    public enum PieceType { none, green, blue, red, yellow, purple };
    public PieceType type;
    public Sprite sprite;
    public int row;
    public int column;
}
```
**Clase para representar el juego**

Crear una clase `Game` que represente el juego completo:
```csharp
public class Game : MonoBehaviour
{
    public int rows;
    public int columns;
    public GamePiece[,] gamePieces;
    public List<GamePiece> selectedPieces;
    public int score;
    public int level;

    public void StartGame()
    {
        InitializeGame();
    }

    public void InitializeGame()
    {
        // Inicializar la grid con piezas aleatorias
        gamePieces = new GamePiece[rows, columns];
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            {
                GamePiece piece = new GamePiece();
                piece.type = (GamePiece.PieceType)Random.Range(0, 6);
                piece.sprite = GetSprite(piece.type);
                piece.row = i;
                piece.column = j;
                gamePieces[i, j] = piece;
            }
        }
    }

    public void Update()
    {
        // Verificar si se detectó un match
        CheckForMatch();
    }

    public void CheckForMatch()
    {
        // Verificar si hay al menos 3 piezas conectadas
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            {
                // Verificar direcciones (arriba, abajo, izquierda, derecha)
                if (IsValidMatch(i, j))
                {
                    // Realizar el match
                    MatchPieces(i, j);
                }
            }
        }
    }

    public void MatchPieces(int row, int column)
    {
        // Eliminar las piezas matcheadas
        List<GamePiece> matchedPieces = new List<GamePiece>();
        for (int i = -1; i <= 1; i++)
        {
            for (int j = -1; j <= 1; j++)
            {
                int newRow = row + i;
                int newColumn = column + j;
                if (newRow >= 0 && newRow < rows && newColumn >= 0 && newColumn < columns)
                {
                    GamePiece piece = gamePieces[newRow, newColumn];
                    if (piece.type != GamePiece.PieceType.none)
                    {
                        matchedPieces.Add(piece);
                    }
                }
            }
        }
        // Añadir bonus por match
        foreach (GamePiece piece in matchedPieces)
        {
            score += piece.type switch
            {
                GamePiece.PieceType.green => 10,
                GamePiece.PieceType.blue => 20,
                GamePiece.PieceType.red => 30,
                GamePiece.PieceType.yellow => 40,
                GamePiece.PieceType.purple => 50,
                _ => 0
            };
        }
        // Eliminar las piezas matcheadas y rellenar la grid
        foreach (GamePiece piece in matchedPieces)
        {
            piece.type = GamePiece.PieceType.none;
            piece.sprite = null;
        }
        // Reemplazar las piezas eliminadas con nuevas
        for (int i = 0; i < matchedPieces.Count; i++)
        {
            GamePiece newPiece = new GamePiece();
            newPiece.type = (GamePiece.PieceType)Random.Range(0, 6);
            newPiece.sprite = GetSprite(newPiece.type);
            gamePieces[matchedPieces[i].row, matchedPieces[i].column] = newPiece;
        }
    }
}
```
