using namespace std;

const double alpha = 1.0; // adjust this value if needed
const double gamma = 1.0; // adjust this value if needed
const double mu = 1.0; // adjust this value if needed
const double h0 = 50e-6; // Initial condition at z=0
const double p0 = 1100;

double M(double zeta, double h) {
  return (zeta*zeta*zeta*zeta * alpha*alpha) / (16*mu) * (3*pow(1 + h/alpha, 4) - 4*pow(1 + h/alpha, 2) + 1 - 4*pow(1 + h/alpha, 4)*log(1 + h/alpha));
}

double p(double zeta, double h, double dh_dz) {
  return -gamma * ((zeta>0) ? (pow(dh_dz, 2) / (1 + pow(dh_dz, 2))^(3/2)) - (1 - alpha*dh_dz) / ((alpha + h) *sqrt(1 + pow(dh_dz, 2))) : 0);
}

// Initial condition
double h_ic(double zeta) {
  return h0 + 162e-6 * (1 - tanh((zeta - 30))));
}

int main() {
  int nx = 100; //_number of grid points in z-direction
  int nt = 100; // number of time steps

  double dx = 0.1; // grid spacing in z-direction
  double dt = 0.001; // time step

  vector<double> h(nx, 0), h_prev(nx, 0);
  vector<double> p(nx, 0);

  // Boundary conditions
  h[0] = h0;
  p[0] = p0;

  // Initial condition
  for (int i = 1; i < nx; i++) {
    h[i] = h_ic(i*dx);
  }

  // Time-stepping loop
  for (int n = 0; n < nt; n++) {
    // Spatial derivatives
    for (int i = 1; i < nx - 1; i++) {
      double dh_dz = (h[i + 1] - h[i - 1]) / (2*dx);
      double M_val = M(i*dx, h[i]);
      double P_val = p(i*dx, h[i], dh_dz);
      double denominator = (i*dx*alpha + h[i]) * M_val + dh_dz;
      h[i] = h[i] - dt * (P_val - M_val * dh_dz) / denominator;
    }

    // Boundary conditions
    h[0] = h0;
    p[0] = p0;

    // Print results
    if (n % 10 == 0) {
      cout << "t = " << n*dt << endl;
      for (int i = 0; i < nx; i++) {
        cout << h[i] << " ";
      }
      cout << endl;
    }
  }

  return 0;
}
