```
// Representación del nodo de un árbol binario
struct Node {
    int value;
    Node* left;
    Node* right;
};

// función para crear un nuevo nodo
Node* newNode(int value) {
    Node* newNode = new Node();
    newNode->value = value;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// función para insertar un valor en el árbol binario
Node* insertNode(Node* root, int value) {
    if (root == NULL) {
        return newNode(value);
    }

    if (value < root->value) {
        root->left = insertNode(root->left, value);
    } else if (value > root->value) {
        root->right = insertNode(root->right, value);
    } else {
        // El valor ya existe en el árbol, no necesitamos insertarlo nuevamente
        return root;
    }

    return root;
}

// función para buscar un valor en el árbol binario
bool searchNode(Node* root, int value) {
    if (root == NULL || root->value == value) {
        return true;
    }

    if (value < root->value) {
        return searchNode(root->left, value);
    } else {
        return searchNode(root->right, value);
    }
}

int main() {
    // Crear un árbol binario
    Node* root = NULL;
    root = insertNode(root, 5);
    root = insertNode(root, 2);
    root = insertNode(root, 8);
    root = insertNode(root, 3);
    root = insertNode(root, 9);

    // Buscar un valor en el árbol binario
    int value = 8;
    if (searchNode(root, value)) {
        std::cout << "El valor " << value << " fue encontrado en el árbol." << std::endl;
    } else {
        std::cout << "El valor " << value << " no fue encontrado en el árbol." << std::endl;
    }

    return 0;
}
```
