```python
import heapq

class Node:
    def __init__(self, name):
        self.name = name
        self.distance = float('inf')

class FibonacciHeap:
    def __init__(self):
        self.min_node = None
        self.heap = []

    def insert(self, node, distance):
        node.distance = distance
        heapq.heappush(self.heap, (distance, node))
        if not self.min_node:
            self.min_node = node

    def update(self, node, distance):
        node.distance = distance
        heapq.heapify(self.heap)
        if node.distance < self.min_node.distance:
            self.min_node = node

    def get_min_distance(self):
        return self.min_node.distance

    def get_min_node(self):
        return self.min_node

    def remove_min(self):
        min_distance, self.min_node = heapq.heappop(self.heap)
        return min_distance

def shortest_path_length(line_length, start, destination):
    unknown_points = FibonacciHeap()
    known_points = set()
    unknown_points.insert(Node(start), 0)

    while True:
        min_distance = unknown_points.remove_min()
        min_node = unknown_points.get_min_node()
        known_points.add(min_node.name)

        if min_node.name == destination:
            return min_distance

        for node, distance in line_length.items():
            if node not in known_points:
                continue
            neighbor_distance = min_distance + distance
            if neighbor_distance < unknown_points.get_min_node().distance:
                unknown_points.update(Node(node), neighbor_distance)

